package cli

import "strings"

// Command help is self-contained so agents never need to hand-format Markdown.
func commandHelp(command string) string {
	usage := map[string]string{
		"install":   "install jcode [--all-instances | --jcode-home PATH] [--dry-run] | install commit-msg [--dry-run]",
		"setup":     "setup",
		"uninstall": "uninstall jcode [--all-instances | --jcode-home PATH] [--dry-run] | uninstall commit-msg [--dry-run]",
		"init":      "init", "new": `new "title" --goal "outcome" --accept "observable check" [flags]`,
		"search": `search WORDS [--state STATE] [--type TYPE] [--epic EPIC] [--label LABEL] [--mine] [--limit N]`, "ls": "ls [--state todo|doing|done|dropped] [--type TYPE] [--priority LABEL] [--label LABEL] [--group FOLDER] [--epic EPIC] [--mine] [--jsonl]",
		"show": "show ID", "edit": "edit ID", "move": "move ID (--before ID | --after ID | --top)", "mv": "mv ID GROUP",
		"take": "take ID --model MODEL [--as NAME] [--with ACTIVE]", "done": `done ID [--reflect "TEXT"]`, "reflections": "reflections [--all] [--by-instruction] | reflections resolve ID N applied|dismissed", "check": `check ID N ["evidence"] [--as NAME]`, "strike": `strike ID N --reason "why"`, "promote": "promote ID N", "note": `note ID "text" [--as NAME]`,
		"set":  `set ID [--title "title"] [--type TYPE] [--priority LABEL] [--label LABEL] [--tag NAME|OLD=NEW|OLD=]... [--state STATE] [--assignee NAME] [--parent EPIC|none] [--goal TEXT] [--purpose TEXT] [--principle TEXT] [--details TEXT] [--accept TEXT]...`,
		"drop": `drop ID "reason"`, "wait": `wait ID [--until YYYY-MM-DD] "on what"`, "ask": `ask ID --to NAME [--check N] [--show FILE] [--after YYYY-MM-DD] "question"`, "resume": "resume ID", "request": `request ID[,ID...] "what you want changed" [--task ID ...] | request ID - [--as NAME]`, "resolve": `resolve ID N "what changed" | resolve ID N - [--as NAME]`, "requests": "requests [ID] [--all]", "coordinator": "coordinator [NAME | --clear]", "memory": "memory [share | local]", "review": "review ID --by NAME [--show FILE]", "answer": `answer ID [N] "the answer" | answer ID [N] - [--as NAME]`, "design": `design ID "question" --for NAME [--show FILE] [--as NAME] | design ID --clear`, "dep": "dep ID [--add REF ...] [--remove REF ...]", "next": "next [--type TYPE] [--priority LABEL] [--label LABEL] [--group FOLDER] [--epic EPIC] [--mine]",
		"rebalance": "rebalance [ID ...]", "types": "types", "states": "states", "people": `people [add SHORT EMAIL [--name "Long Name"]]`, "tags": "tags [add NAME]", "models": "models [add MODEL-ID LEVEL...]", "lint": "lint [ID] [--summary] [--code [CODE]]", "sync": "sync", "deduce": "deduce [--since REV]", "import": "import backlog DIRECTORY [--dry-run] [--cleanup] | import github [OWNER/REPO] [--dry-run] | import files DIR [--cite PREFIX] [--dry-run]", "board": "board [--all] [--wide] [--type TYPE] [--priority LABEL] [--label LABEL] [--group FOLDER] [--epic EPIC] [--mine]", "tui": "tui", "mcp": "mcp", "upgrade": "upgrade [--apply] | upgrade --tags [--min N] [--apply]", "attach": `attach ID FILE... [--name NAME] [--note "what this shows"] [--replace] | attach ID --content TEXT --name NAME`, "detach": "detach ID NAME", "help": "help [COMMAND]",
	}
	details := map[string]string{
		"attach":      "Copies files (or a folder, recursively) into the task's own folder on the task branch, and notes each one\nas file:NAME (size, sha256) in ## Notes, with --note TEXT after it. hug tui shows them in FILES; Space views one.\n--name NAME stores one file under another name. A name that already holds other content is refused;\n--replace overwrites it and the note names the old sha256. --content TEXT --name NAME attaches text with no file.\nA file that looks like a secret is refused; --safe-reason TEXT says why it is not one.\nExample: hug task attach k7m2qx run.log screen.png --note \"CI run 44188866860\"\n",
		"detach":      "Removes a file from the task's folder and notes it. NAME is the name shown in FILES.\nExample: hug task detach k7m2qx run.log\n",
		"setup":       "Prints what an agent needs to switch this repository to hug tasks, then a checklist of the steps still open, each with the exact command or edit. Reads only; changes nothing. Re-run after each step.\n",
		"install":     "Adds hug's MCP server (an entry named hug running hug mcp --jcode-home that instance: the task_* and memory_* tools) to Jcode mcp.json, in place of the entry an older hug added under its part's name. Keeps a timestamped backup and other servers. Default: JCODE_HOME or ~/.jcode. --all-instances discovers the static zsh registry. Restart Jcode afterward.\ninstall commit-msg: refuse commits without exactly one Model: trailer, the model id that made the\ncommit and the effort it ran at (Model: claude-opus-5-5/high), or Model: human when the git author\nwrote it (t709he, jr55s8). A model's levels are its line in hug.toml [models] on the hug/tasks branch\n(hug task models add ID LEVEL...); without a [models] table any of none, minimal, low, medium, high,\nxhigh, max goes. It goes into this clone's\n<git-common-dir>/hooks; a hook already there keeps running first, as commit-msg.pre-hug. With\ncore.hooksPath (a project's own .githooks) hug never edits the tracked hook: it writes the gate as\n<git-common-dir>/hooks/hug-commit-msg and the tracked commit-msg calls it in two lines, after #!/bin/sh:\n" + tailLines + "\nhug task setup lists that step until they are there. Merges, rebases,\ncherry-picks, reverts, fixup!/squash! and the hug/tasks and muninn-notes branches are exempt;\nhug's own board commits add Model: from --model or HUG_MODEL. Emergency exit: git commit --no-verify.\nList commits by model: git log --format='%h %(trailers:key=Model,valueonly,separator=%x2C) %s', or one model:\ngit log --grep='^Model: gpt-6.1-sol/'.\n",
		"models":      "Lists hug.toml [models]: each model id and the effort levels it runs at, which the commit-msg gate\nchecks a Model: <id>/<effort> trailer against (jr55s8). add ID LEVEL... writes the model's line, replacing\none already there, and commits it on hug/tasks.\n",
		"uninstall":   "Removes only the hug MCP entry install added (or an older hug's entry under its part's name), keeping backups and other servers. Same instance selection as install.\nuninstall commit-msg removes hug's Model: gate and puts back a hook it had kept as commit-msg.pre-hug.\n",
		"new":         "Required: --goal (where we aim), --purpose (why), --principle (what we do and do not do) and at\nleast one --accept TEXT; repeat --accept for each check. --details is optional (only facts a decision\ndepends on). A missing part is named with every other one, and one fix: line gives the whole command.\nThe Goal is one sentence of at most 140 characters; detail goes in Details. new and set refuse a longer\nGoal (goal-too-long) with fix: hug task set ID --goal \"one sentence\" --details \"...\"; lint warns on one on disk.\nOptional: --type feature|bug|chore|spike|docs (default feature), --priority LABEL.\nRepeat --dep REF for dependencies and --label LABEL for labels.\nUse --group FOLDER, --top, or --after REF to choose placement.\nExample: hug task new \"Form\" --goal \"Submit works\" --purpose \"Users save drafts\" --principle \"Server validates\" --accept \"Saved\"\n",
		"ls":          "Columns: id, state, type, slug, title. All states are included unless filtered. Filters combine.\n--jsonl prints one JSON task per line; --json one object with a tasks array.\n--mine is the name take records: --as, HUG_USER, the agent session, else --model/HUG_MODEL.\n",
		"show":        "Shows goal, notes, numbered acceptance and dependency ids with current titles/states/paths.\nA task with lint findings ends with the same block as hug task lint ID: each finding, then one fix: line.\n",
		"edit":        "Runs $EDITOR, commits the edited task and reports lint findings.\nPrefer check, note and set for non-interactive changes.\n",
		"move":        "Changes filename rank only, repairing neighbouring ranks automatically if needed.\nUse mv to change folder.\n",
		"mv":          "Moves the task to a folder without changing its id, rank or contents.\nExample: hug task mv k7m2qx auth\n",
		"take":        "Pulls, checks dependencies and ownership, sets doing, commits and pushes as a lock.\n--model MODEL is required (or HUG_MODEL): the model doing the work, such as claude-opus-5-5\nor gpt-6.1-sol; a person gives --model human. --as NAME (or HUG_USER, or the agent session,\njcode: the name in JCODE_SESSION_ID) is optional; without a name the assignee is the model.\ngit config user.name is never used. Both are recorded: assignee and model.\nExample: hug task take k7m2qx --as poodle --model claude-opus-5-5\nRepeating take on your own doing task succeeds without changing it.\nOne ticket in doing per agent: while you have a doing task that is active, a second take is\nrefused naming it, with five fixes: finish it (hug task done ID), park it (hug task wait ID\n\"on what\"), give it back (hug task set ID --state todo, with a note), make this take a detour\n(hug task dep ID --add THIS && hug task note ID \"where I was\": ID is active again when THIS is done),\nor take it with ID (byj479). --with ACTIVE takes a todo task alongside ACTIVE, your active task, when\nthey ship together (one change or release): both are doing, this one marked doing_with ACTIVE and\nshown \"with ACTIVE\"; each closes on its own. --with any other task is refused.\nA task waiting, in review or depending on another one does not count.\n",
		"done":        "Only a doing task becomes done: take it first (a todo task is refused with the take as the fix).\nBlocks on open dependencies and unchecked acceptance (exit 3 with exact fixes).\nTick every acceptance item first, or strike out one that no longer applies (hug task strike). There is no --force. Repeating done succeeds.\nDone asks one question: did the instructions (AGENTS.md, tool descriptions, hug messages)\nguide you well, or did one mislead you or leave a gap? --reflect TEXT stores the answer\nas a Reflection note on the task, after done succeeds; quote the instruction and say what\nhappened. \"nothing\" is a fine answer. Repeat done with --reflect to answer afterwards.\nA done without an answer is recorded as Reflection (unanswered, DATE, WHO), so the answer\nrate shows; a later answer, or \"nothing\", takes its place.\n",
		"reflections": "Lists open reflections across the board: task, date, who, the instruction quoted and the text,\nthen how many dones came without an answer. --all includes applied and dismissed ones.\n--by-instruction groups them by what they name (the hug command in the quote, else the quote,\nelse a hug command in the text), the largest group first: repeats of one gap show together.\nA reviewer turns one into an instruction change (shown as a diff), then:\nhug task reflections resolve ID N applied; or dismissed. N counts the task's reflections from 1.\n",
		"promote":     "Turns acceptance item N into its own task, ranked right after ID in the same group and under\nthe same epic (an epic's item becomes its child). The item then reads 'done when task:NEW is done'\nand is ticked automatically when NEW is done.\nExample: hug task promote k7m2qx 2\n",
		"strike":      "Strikes acceptance item N out as not relevant, with --reason (required): why it no longer\napplies. The text stays, crossed through, with the reason, who (--as, HUG_USER, the agent\nsession or --model) and the day: - [ ] ~~TEXT~~ (not relevant: REASON, NAME, DATE).\ndone counts a struck check as settled. --undo restores it as an open check. A ticked item\ncannot be struck (it was done). show prints it as N. [-] ~~TEXT~~ (not relevant: ...).\nExample: hug task strike k7m2qx 2 --reason \"replaced by the API test in item 3\"\n",
		"tags":        "Lists the board's tags: hug.toml tags = [...] at the top level (txjkrm). Tags carry no meaning to hug: display,\nfilter, group only. With a list, lint flags an open task's tag not on it (unlisted-tag): a variant of a listed tag (case,\n- or _, or [tag_merges] OLD = \"LISTED\") with hug task set ID --tag OLD=LISTED, any other with hug task tags add NAME\nor hug task set ID --tag NAME= (removes it). No list: no task's tags are judged.\nadd NAME adds one tag to the list, once.\nExample: hug task tags add parser\n",
		"check":       "Ticks acceptance item N, numbered from 1 in show output. Repeating it succeeds.\nWith \"evidence\" (- reads it from stdin) the same write notes \"check N: evidence\": what shows it holds.\nThe person a question is asked of (hug task ask --check N) ticking that check answers it (qsqhpe): History says\n'answered by ticking check N', the task is active again and the asker sees it, as with hug task answer.\nExample: hug task check k7m2qx 1 \"TestRetry passes: ok ./retry 0.4s\"\n",
		"note":        "Appends text to Notes, preserving existing content.\nExample: hug task note k7m2qx \"Blocked on p3rt9a; waiting for API\"\n",
		"set":         "Types: feature|bug|chore|spike|docs. States: todo|doing|done|dropped.\nPriority is a free label. --label and --assignee replace the field with one value.\n--tag NAME adds one tag, --tag OLD=NEW replaces one, --tag OLD= removes one (repeatable; running it again changes\nnothing). hug task tags lists the board's tags (hug.toml tags = [...]); lint flags a tag not on it (unlisted-tag).\n--state todo gives your task back (keeping its stage) or reopens a done or dropped one; the old\nnode's fields move to ## History. State done still enforces dependencies and acceptance. Use take to claim work.\n--parent EPIC puts the task under an epic (epic > task > acceptance item; an epic has no parent);\n--parent none clears it. An epic is done only when its children are done or dropped.\n--goal, --purpose, --principle and --details replace that section's text (the Goal is one sentence of at\nmost 140 characters; detail goes in Details); --accept (repeatable) adds an\nunchecked item. Every lint fix: line is a set command, so no editor is needed. The reply says first what\nthe set wrote, one line per changed field (\"added check N: ...\"), then what lint still finds on the\ntask, with one fix: line for all of it.\n",
		"dep":         "Add or remove dependency references, stored as immutable ids. Repeat --add/--remove.\nRepeats are no-ops. A dependency cycle blocks with exit 3 and an exact fix.\nA dependency on an epic waits until all its children are done or dropped.\nA condition waits too: --add \"when PREDICATE\" with date YYYY-MM-DD, load below N (5-min average),\nbranch NAME merged, release NAME exists (a tag), task:ID closed, group NAME closed (or --add group:NAME);\nadd \"wakes NAME\" to say who it wakes (default: whoever took the task). next skips the task and take\nrefuses until it holds; a task or group condition also holds back done. Remove it by what it says.\nExample: hug task dep k7m2qx --add p3rt9a\nExample: hug task dep k7m2qx --add \"when load below 120\" --add group:auth\n",
		"drop":        "Marks a task dropped even when blocked, with the reason (dropped_reason). Does not delete the file.\nRepeating it succeeds. hug task set ID --state todo reopens it; the reason moves to ## History.\n",
		"wait":        "Your doing task waits on a thing outside the board with no person to answer (CI, a release): stage\nwaiting, waiting_on and waiting_since are written. hug task resume ID ends the wait.\n--until YYYY-MM-DD (your local day) ends it on its own: on the first hug read that day the task is doing/active\nagain, first in your hug task next --mine, with one History line. Waiting for time to pass is a wait like CI.\nA question to a person is\nnot a wait: hug task ask ID --to NAME \"...\". On a board with hug.toml [people], wait refuses one (agxqax): a text that\nopens with \"owner:\" or a person's name (\"jhf:\", \"Jørgen:\"), with \"the owner's decision\", or with \"owner confirms ...\" is\nrefused with the ask that says it. A dependency on another task is not a wait either: hug task dep ID --add OTHER.\n",
		"ask":         "Your doing task asks a person something and can't go on until they answer (41hhgn): stage asked.\n--to NAME (required) is who answers, asked_for: their short name in hug.toml [people] or an agent's name; they\nsee it in hug tui as asked: you, first in their list. Another name for a person resolves to the short name\n(agxqax: --to jorgen, --to Jørgen, --to \"Jørgen H. Fjeld\" and an alias = [\"...\"] in their [people] entry all write\njhf); on a board with [people], a name that is nobody there and no agent working on the board is refused.\n--check N names the acceptance check it is about (asked_check); a ticked check is refused (a tick is the answer).\n--show FILE names one of the task's files to look at (asked_show; attach it first), drawn under the question. The\nquestion may span lines and is kept verbatim. Ask one question per ask (q2adr8): a numbered list of questions in one\nask is refused; ask each on its own. Each is numbered in the task's ## Questions and answered on its own, with\nhug task answer ID N or by ticking its check; the task stays asked until every one is answered, then you are active again.\n--after YYYY-MM-DD asks it that day, not now: until then the task waits (doing/waiting, 'until DATE') and is in\nnobody's ASKED; on the first hug read that day it is asked as written (z2vmte). For a question that can only be\nanswered later.\nOn a todo task (yphbra) anyone may ask without taking it: the question goes in ## Questions the same way, the task\nstays todo with its assignee and dependencies, design_* show the oldest open one, and it is in the person's ASKED\nat once, even while a dependency is open (the asker chose to ask now). Answers go to the asker. Taking the task keeps\nthe open questions: it is doing/asked. --after needs your doing task. Unlike hug task design, whose question waits\nfor the task's dependencies before it is in anyone's ASKED (the 11-17 order: deferred, depends, design).\n",
		"review":      "Your doing task asks for a review: doing/active becomes doing/review and you keep it (6w0gve).\n--by NAME (required) is who reviews, review_by: a person's short name in hug.toml [people] or an agent's\nname; they see it in hug tui as review: you. --show FILE names one of the task's files to look at (review_show;\nattach it first), drawn under the review question. The reviewer answers: hug task answer ID \"looks right\"\n(or what to change); the review fields go to History and you are active again. done stays your own step.\n",
		"request":     "A person's request on a task, in their own words (hbgybn): what they want changed, no form, no field named.\nKept verbatim under ## Requests with who (--as, HUG_USER or the agent session) and when, numbered 1, 2, ... per task.\nREQUEST - reads it from stdin; it may span lines. It does not change the task's stage. The task's assignee hears it\non its next turn (else the coordinator: hug task coordinator; with none set, every session) and hug task next\nlists it first until someone resolves it.\nOne request for several tasks (ec6z6j): request ID1,ID2 \"text\", or --task ID (repeatable). It is written once, on\nthe first task, with the exact IDs; every other task gets a link to it, delivered once. Each task resolves its own\npart (hug task resolve ID N); the request closes when the last one does. An unknown ID writes nothing (exit 2).\n",
		"resolve":     "Closes request N on a task with what you did about it (hbgybn): turn the request into changes to the ticket\n(goal, checks, a new task, a split), then say what changed. The account is kept verbatim under the request with\nwho and when; ACCOUNT - reads it from stdin. If the request is unclear, ask back with hug task ask instead.\n",
		"requests":    "Lists the open requests on the board, oldest first, each with who asked, when, its text and the resolve\ncommand; with ID, that task's; --all includes resolved ones with their accounts.\n",
		"memory":      "Whether hug mem sync may push this repository's project memories to its remote (34r1ft). Kept in hug.toml\n[memory] share = true, committed on the task branch, so every clone follows the repository. share opts in (a private\nrepository); local removes it, the default: sync then says so and pushes nothing. Without a word, says which.\n",
		"coordinator": "Names the board's coordinator (hbgybn): the session that hears what no owner hears, a request on a task\nnobody holds. Kept in hug.toml [board] coordinator, committed on the task branch. Without a name, says who it is;\n--clear removes it (then every session hears an unowned request once).\n",
		"answer":      "Answers the question the task's stage asks: a design question (todo/design), a question asked with\nhug task ask (doing/asked) or a review (review). Agents ask one question per ask, so each has its own answer:\nanswer ID N answers question N (hug task show ID lists them); with one open, answer ID answers it. The answer is\nwritten under its question in ## Questions; the task stays asked until every question is answered. ANSWER - reads the answer from stdin; it may span lines and is kept\nverbatim. One ## History block keeps the question, the answer, who answered (--as, HUG_USER or the agent session)\nand for whom; the stage's fields go and the stage re-derives (design -> ready, asked -> active, review -> ready or\nactive; done stays hug task done). A wait asks nobody: hug task resume ID ends it.\nThe asker sees the answer first in show and next --mine until it next writes on the task.\n",
		"resume":      "Ends a wait, or withdraws your own question: the stage's fields move to ## History and the stage is set\nagain (active, or what holds). Ending a wait prints once what it was waiting on, which is then only in History.\n",
		"design":      "A question must be answered before anyone starts: stage design, with design_question, design_for (--for:\nthe person who must answer, required), design_since and design_asked_by (--as, HUG_USER or the agent\nsession). The person sees it in hug tui as design: you. --show FILE names a task file to look at\n(design_show), shown under the question. --clear when it is answered: the\nquestion moves to ## History and the stage is set again (ready, or what holds).\n",
		"next":        "Plain next: highest-ranked unblocked, unassigned todo that is not an epic (an epic finishes through its children). --epic EPIC limits to that epic. Exit 4 when none match.\n--mine: my unblocked doing first, then todo, in rank order. My waiting tasks are not work now: hug wakes them\n(--until, a condition) or hug task resume ends the wait; with nothing else, it says so (exit 4) and lists them,\none line each. Filters combine.\nTypes: feature|bug|chore|spike|docs. Priority is a free label.\n",
		"rebalance":   "Rekeys the rank prefix of task filenames (e.g. 000000000003.ID.slug.md becomes 00i.ID.slug.md)\nso later moves have room. Task order, ids and contents do not change; it is one commit,\nundone with git revert in .hug/tasks. Usually unnecessary: move rekeys neighbours itself.\nWith IDs, only the span between them is rekeyed.\n",
		"states":      "Prints the state and stage tree from huginn/internal/task/states.go: each state (does anyone have it?),\nits stages (why nobody works on it, or what happens with it now), who sets each, the fields a node carries\nwhile a task is in it, and the transitions the commands make. --json for the table.\n",
		"search":      "Finds tasks by words, best first: BM25 over id, aliases, title, goal, purpose, principle, details,\nacceptance and notes (id, aliases and title count most). Every word must match; ids keep their dashes\n(STATBUS-402, 44w1ev). Each result names the field that matched and a snippet around it.\nThe ls filters narrow the results. --limit N (default 20). Example: hug task search \"memory limit 137\" --state todo\n",
		"lint":        "The board overview: findings (and how many are broken) per code, then one line per task with its codes\nand the command that shows it: ID  code, code  -> hug task lint ID. More than 30 tasks: the first 10 and how to see the rest.\nhug task lint ID: every finding of that task as file:line: SEVERITY [code] problem, then next: is ONE command\nthat fixes all it can (hug task set ID --purpose \"...\" --principle \"...\"; then hug upgrade).\nNever silent: a clean board says \"no findings\".\nSeverity: broken (hug cannot read or trust the task) or advice (it works, below the house style).\nLint judges open tasks only (todo, doing): done and dropped tasks are history, neither shown nor\ncounted, and hug task lint ID on one says so. A task is checked when it closes (done refuses an open\ncheck). A file hug cannot read as a task still shows: nothing says it is closed.\nAdvice: long-title, goal-too-long, no-acceptance, missing-section, section-order, backlog-leftover. Every other code is\nbroken, e.g. dangling-dependency, not-a-dependency, dependency-cycle, missing-goal, duplicate-section,\nparent-too-deep, stale-owner.\n--summary: one line per code with its count, severity, meaning and the command that lists it.\n--code CODE lists one kind finding by finding, each with its fix; --code alone lists every code with its severity.\nEvery open task is held to the description pattern (Goal, Purpose, Principle, Acceptance).\nJSON: findings (path, line, problem, code, severity, fix), tasks_findings (per task: id, codes, findings, fix),\nsummary (total, broken, codes). Every finding: --json.\n",
		"deduce":      "Notes what git says about tickets: a commit whose subject ends with ticket ids, e.g. (16dxsr) or (t709he, 44w1ev), reaching main adds 'landed <sha> on main <date>'; a release tag vX.Y.Z containing it adds 'shipped in vX.Y.Z', or sets done_release on a done ticket.\nEach clone reads only what is new since its last pass; the first pass starts at the current tip. --since REV replays from REV (e.g. v0.7.30). A line is written once per ticket and commit, from any clone.\nIt never ticks a check. At a release (yf39ya) a doing task it contains whose every check and child holds is closed, as hug task done would\n(History: done, by release vX.Y.Z), and one whose open checks are all a person's ('Jørgen confirms after release') is asked of\nthat person, one check at a time; their tick asks the next or closes it. sync and the background pass run it too.",
		"sync":        "Commits local task edits, pulls with rebase and pushes only the task branch (hug/tasks), now.\nYou rarely need it: every change is pushed in the background within seconds (a burst of writes\nis one push), and reads fetch when the last fetch is over 5 s old. Offline or after a conflict,\nhug task ls says 'N unpushed' with this command as the fix; nothing is lost meanwhile.\nHUG_SYNC=off turns the background push off. Its log: .git/hug/sync/hug-tasks.log.\nIt and the background pass also hand a doing task whose workers' sessions all ended to the board's coordinator\n(yf39ya: stage kept, one History line); hug task lint never writes and names this command as stale-owner's fix.\n",
		"upgrade":     "Shows, then with --apply does, every mechanical migration, per part what it changes, or nothing to do (asr4t2):\nlayout: the old huginn branch and .huginn/ become hug/tasks at .hug/tasks/, huginn.toml becomes hug.toml;\ntasks: every status: becomes state: (6ephqk), sections go in order (Goal, Purpose, Principle, Relevant details,\nDepends on, Acceptance, others, Notes, History; no section's text changes), backlog import leftovers go\n(<!-- SECTION:... --> and <!-- AC:... --> lines, created_date, ordinal, backlog_status, import_type_inference),\nand a wait on a person (waiting_for, or an old waiting_on \"NAME: what\" with NAME in hug.toml [people])\nbecomes a question, stage asked (asked_what, asked_for, asked_check from a leading \"check N:\");\nvariables: old names in hook commands and MCP entries become HUG_ names (backups kept);\nmemory: a legacy .muninn/memories.jsonl is named with hug mem sync --migrate.\nPreviews by default: changes nothing, prints each change as would: ... with the diff, and exits 5 with\nfix: hug upgrade --apply when something is pending (0 when there is nothing to do). --apply does it,\none commit per step on hug/tasks. hug task upgrade is the same. Choices stay with hug setup. Safe to run again.\nTwo headings: this board (layout, tasks) and this machine (variables, memory: hook and MCP configs\nin ~/.jcode, ~/.claude, ~/.codex, and the memory store). --apply changes this board only; this machine's\nchanges wait for hug upgrade --apply --machine (exit 5 until then), so an upgrade run for one board never\nreaches files every repository shares (f5vx4x).\ncatch-up: when the remote moved the board to a newer layout and this clone has unpushed commits from\nbefore (sync stops on them, fix: hug upgrade), --apply replays them onto the remote one by one, each with\nits own message; a value both sides changed keeps the board's and puts this clone's in a note (w40cmk).\n--tags (txjkrm): cleans task labels against hug.toml tags, its own step: variants of a listed tag merge on\nevery task; on open tasks a type or priority label the field says goes (one that disagrees stays, listed),\nparked/paused/deferred on a todo task make it deferred, draft and unlisted labels go. Done and dropped tasks\nget merges only. No list: one is proposed, the tags on --min (3) or more tasks. Preview, exit 5, then\nhug upgrade --tags --apply writes it in one commit.\n",
		"import": "Imports or re-syncs backlog-md tasks idempotently, preserving old ids as aliases.\nDIRECTORY is the backlog root (e.g. .backlog: reads tasks, drafts, completed and archive in one run;\nwhen an id is in several folders the newest updated_date wins) or a single folder of task files.\nRe-running merges backlog changes; edits made in hug win. --dry-run reports without writing.\n" +
			"import backlog DIRECTORY --cleanup ends the move, once every task is in: one commit on your branch removes\n" +
			"DIRECTORY with git rm (history keeps it), backlog's MCP server and its BACKLOG.MD block in AGENTS.md/CLAUDE.md,\n" +
			"and hug.toml records source, commit and date. With --dry-run it shows the diff and the agent: lines (hooks,\n" +
			"scripts and settings that still use backlog, which hug never edits). After it, importing DIRECTORY again is\n" +
			"refused, naming the commit that holds the old copy; a leftover DIRECTORY is removed by --cleanup again.\n" +
			"import github reads every issue (open and closed) of OWNER/REPO, or of this repository, through the gh CLI:\n" +
			"alias GH-<number>, labels and assignees kept, task-list checkboxes become acceptance items,\n" +
			"closed becomes done, closed as not planned becomes dropped. Re-run to sync; edits made in hug win.\n",
		"tui":   "Interactive ranked list and board. For non-interactive output use board or ls --json.\n",
		"board": "Prints todo, doing and done side by side in rank order; blocked tasks are marked.\nDone shows the last 5 unless --all. Filters match ls. --json gives the columns.\n",
		"mcp":   "Runs the standard-I/O MCP server with ten flat tools and next-step hints.\n",
	}
	return "hug task " + usage[command] + "\n" + details[command] + "Refs accept ids, unique prefixes, slugs and aliases case-insensitively.\nAdd --json for structured output.\nnext: hug task next\n"
}
func isJSONL(args []string) bool {
	for _, a := range args {
		if a == "--jsonl" {
			return true
		}
	}
	return false
}
func isJSON(args []string) bool {
	for _, a := range args {
		if a == "--json" || strings.HasPrefix(a, "--json=") {
			return true
		}
	}
	return false
}
